34	export default async function ShiftsPage({
35	  params,
36	}: {
37	  params: Promise<{ businessId: string }>;
38	}) {
39	  const { businessId } = await params;
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: shiftRows } = await supabase
53	    .from("shifts")
54	    .select(
55	      "id, opened_at, closed_at, opening_cash, closing_cash, cash_sales, non_cash_sales, total_sales, expected_cash, difference, tx_count, void_count, close_notes, cashiers(name)",
56	    )
57	    .eq("business_id", businessId)
58	    .not("closed_at", "is", null)
59	    .order("closed_at", { ascending: false })
60	    .limit(50);
61	
62	  const shifts = (shiftRows ?? []) as unknown as ShiftRow[];
63	
64	  return (
65	    <div className="w-full max-w-2xl">
66	        <h1 className="text-lg font-bold text-zinc-900">
67	          Riwayat Shift — {business.name}
68	        </h1>
69	        <p className="mt-1 text-sm text-zinc-500">50 shift terakhir yang sudah ditutup.</p>
70	
71	        <div className="mt-6 space-y-2">
72	          {shifts.length > 0 ? (
73	            shifts.map((s) => {
74	              const diff = Number(s.difference);
75	              return (
76	                <div
77	                  key={s.id}
78	                  className="rounded-xl border border-zinc-200 bg-white px-4 py-3"
79	                >
80	                  <div className="flex items-center justify-between">
81	                    <p className="text-sm font-medium text-zinc-900">
82	                      {s.cashiers?.name ?? "Kasir terhapus"}
83	                    </p>
84	                    <p className="text-sm font-semibold text-zinc-900">
85	                      {formatRupiah(Number(s.total_sales))}
86	                    </p>
87	                  </div>
88	                  <p className="mt-0.5 text-xs text-zinc-500">
89	                    {formatDateTime(s.opened_at)} – {formatDateTime(s.closed_at)}
90	                  </p>
91	
92	                  <div className="mt-2 grid grid-cols-3 gap-2 rounded-lg bg-zinc-50 px-3 py-2 text-center">
93	                    <div>
94	                      <p className="text-[10px] text-zinc-400">Transaksi</p>
95	                      <p className="text-xs font-semibold text-zinc-900">{s.tx_count}</p>
96	                    </div>
97	                    <div>
98	                      <p className="text-[10px] text-zinc-400">Kas Diharapkan</p>
99	                      <p className="text-xs font-semibold text-zinc-900">
100	                        {formatRupiah(Number(s.expected_cash))}
101	                      </p>
102	                    </div>
103	                    <div>
104	                      <p className="text-[10px] text-zinc-400">Selisih</p>
105	                      <p
106	                        className={`text-xs font-semibold ${
107	                          diff === 0
108	                            ? "text-zinc-900"
109	                            : diff > 0
110	                              ? "text-brand-700"
111	                              : "text-red-600"
112	                        }`}
113	                      >
114	                        {diff === 0 ? "Pas" : `${diff > 0 ? "+" : ""}${formatRupiah(diff)}`}
115	                      </p>
116	                    </div>
117	                  </div>
118	
119	                  {s.void_count > 0 && (
120	                    <p className="mt-1.5 text-[11px] text-red-500">
121	                      {s.void_count} transaksi dibatalkan
122	                    </p>
123	                  )}
124	                  {s.close_notes && (
125	                    <p className="mt-1.5 text-[11px] text-zinc-400">Catatan: {s.close_notes}</p>
126	                  )}
127	                </div>
128	              );
129	            })
130	          ) : (
131	            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
132	              Belum ada shift yang ditutup.
133	            </p>
134	          )}
135	        </div>
136	    </div>
137	  );
138	}
