6	export default function PrintButton({
7	  businessId,
8	  transactionId,
9	}: {
10	  businessId: string;
11	  transactionId: string;
12	}) {
13	  // Struk dibuka dari POS lewat link baru (target="_blank") khusus untuk
14	  // dicetak — auto-buka dialog print begitu halaman selesai render, supaya
15	  // kasir tidak perlu klik "Cetak" lagi secara manual. Guard `printed` biar
16	  // tidak dobel kepanggil (mis. React StrictMode di dev me-render efek 2x).
17	  const printed = useRef(false);
18	  useEffect(() => {
19	    if (printed.current) return;
20	    printed.current = true;
21	    window.print();
22	  }, []);
23	
24	  return (
25	    <div className="flex gap-2">
26	      <Link
27	        href={`/business/${businessId}/transactions/${transactionId}`}
28	        className="flex flex-1 items-center justify-center rounded-xl border border-zinc-200 bg-white py-2.5 text-sm font-medium text-zinc-600 hover:bg-zinc-50"
29	      >
30	        ← Kembali
31	      </Link>
32	      <button
33	        onClick={() => window.print()}
34	        className="flex-1 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white hover:bg-brand-700"
35	      >
36	        🖨️ Cetak
37	      </button>
38	    </div>
39	  );
40	}
